import type { Column, Typed } from '../Column'

/**Date format yyyy-MM-dd*/
type DateColumnTypeFormat = `${number}-${number}-${number}`

/**Date format yyyy-MM-dd HH:MM:SS*/
type DateTimeColumnTypeFormat = `${number}-${number}-${number} ${number}:${number}:${number}`

export type DateColumnType<
    Type extends DateColumnTypeFormat = DateColumnTypeFormat,
    Default extends Type = Type,
> = Column<Type, Default>

/**
 * A Column for a date type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 */
export function DateColumn<
    const Type extends DateColumnTypeFormat,
    const Default extends Type,
    const C extends Column<Type, Default>,
>(config: C & DateColumnType<Type, Default>) {
    return config as Typed<Type, C>
}

/**
 * A Column for a datetime type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 */
export function DateTimeColumn<
    const Type extends DateTimeColumnTypeFormat,
    const Default extends Type,
    const C extends Column<Type, Default>,
>(config: C & Column<Type, Default>) {
    return config as Typed<Type, C>
}

